changeSet.sql:
CREATE TABLE section_chats (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  section_id bigint NOT NULL REFERENCES sections(id) ON DELETE CASCADE,
  nom varchar(100) NOT NULL,
  CONSTRAINT uq_section_chat_name UNIQUE (section_id, nom)
);
CREATE TABLE section_chat_permissions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  section_chat_id bigint NOT NULL REFERENCES section_chats(id) ON DELETE CASCADE,
  role varchar(32) NOT NULL,
  ecriture boolean NOT NULL,
  CONSTRAINT uq_section_chat_role UNIQUE (section_chat_id, role)
);
CREATE TABLE section_chat_reads (
  user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  section_chat_id bigint NOT NULL REFERENCES section_chats(id) ON DELETE CASCADE,
  last_message_id bigint NOT NULL,
  PRIMARY KEY (user_id, section_chat_id)
);
ALTER TABLE activity_chat_messages ADD COLUMN section_chat_id bigint REFERENCES section_chats(id) ON DELETE CASCADE;
CREATE INDEX idx_activity_chat_section_chat_id ON activity_chat_messages (section_chat_id, id);
